    ["Savage Rend"]={de="Wildes Verwunden", en="Savage Rend", es="Desgarro salvaje", fams={"raptor"}, fr="Pourfendeur sauvage", icon=132193, kind="special", ranks={{de="Schlitzt einen Gegner mit rasiermesserscharfen Krallen auf und fügt ihm so im Verlauf von 18 Sek. 30 Blutungsschaden zu.", en="Slash an enemy with razor talons, causing the target to Bleed for 30 damage over 18 sec.", id=1265065, l=12, r=1}, {de="Schlitzt einen Gegner mit rasiermesserscharfen Krallen auf und fügt ihm so im Verlauf von 18 Sek. 54 Blutungsschaden zu.", en="Slash an enemy with razor talons, causing the target to Bleed for 54 damage over 18 sec.", id=1265066, l=24, r=2}, {de="Schlitzt einen Gegner mit rasiermesserscharfen Krallen auf und fügt ihm so im Verlauf von 18 Sek. 72 Blutungsschaden zu.", en="Slash an enemy with razor talons, causing the target to Bleed for 72 damage over 18 sec.", id=1265067, l=36, r=3}, {de="Schlitzt einen Gegner mit rasiermesserscharfen Krallen auf und fügt ihm so im Verlauf von 18 Sek. 120 Blutungsschaden zu.", en="Slash an enemy with razor talons, causing the target to Bleed for 120 damage over 18 sec.", id=1265068, l=48, r=4}, {de="Schlitzt einen Gegner mit rasiermesserscharfen Krallen auf und fügt ihm so im Verlauf von 18 Sek. 156 Blutungsschaden zu.", en="Slash an enemy with razor talons, causing the target to Bleed for 156 damage over 18 sec.", id=1265069, l=60, r=5}}, ru="Жестокое кровопускание", taught={[1]=2}, zh="野蛮撕扯"},
    ["Scorpid Poison"]={de="Skorpidgift", en="Scorpid Poison", es="Veneno de escórpido", fams={"scorpid"}, fr="Poison de scorpide", icon=132274, kind="special", ranks={{de="Fügt 10 Sek. lang, 5 Punkt(e) Naturschaden zu. Effekt ist auf einem einzelnen Ziel bis zu 5-mal stapelbar.", en="Inflicts 5 Nature damage over 10 sec. Effect can stack up to 5 times on a single target.", id=24640, l=8, r=1}, {de="Fügt 10 Sek. lang 10 Punkt(e) Naturschaden zu. Effekt ist auf einem einzelnen Ziel bis zu 5-mal stapelbar.", en="Inflicts 10 Nature damage over 10 sec. Effect can stack up to 5 times on a single target.", id=24583, l=24, r=2}, {de="Fügt 10 Sek. lang, 20 Punkt(e) Naturschaden zu. Effekt ist auf einem einzelnen Ziel bis zu 5-mal stapelbar.", en="Inflicts 20 Nature damage over 10 sec. Effect can stack up to 5 times on a single target.", id=24586, l=40, r=3}, {de="Fügt 10 Sek. lang, 25 Punkt(e) Naturschaden zu. Effekt ist auf einem einzelnen Ziel bis zu 5-mal stapelbar.", en="Inflicts 25 Nature damage over 10 sec. Effect can stack up to 5 times on a single target.", id=24587, l=56, r=4}}, ru="Яд скорпида", taught={[1]=5, [2]=7, [3]=10, [4]=4}, zh="蝎毒"},
